GRANT INHERITED SELECT ON ALL TABLES IN SCHEMA my_db.my_schema
    TO DATABASE ROLE my_db.read_role;

GRANT INHERITED SELECT ON ALL VIEWS IN SCHEMA my_db.my_schema
    TO DATABASE ROLE my_db.read_role;

GRANT INHERITED SELECT ON ALL DYNAMIC TABLES IN SCHEMA my_db.my_schema
    TO DATABASE ROLE my_db.read_role;

GRANT INHERITED SELECT ON ALL ICEBERG TABLES IN SCHEMA my_db.my_schema
    TO ROLE my_role;

GRANT INHERITED USAGE ON ALL FUNCTIONS IN SCHEMA my_db.my_schema
    TO DATABASE ROLE my_db.read_role;

GRANT INHERITED USAGE ON ALL PROCEDURES IN SCHEMA my_db.my_schema
    TO DATABASE ROLE my_db.read_role;

GRANT INHERITED USAGE ON ALL SEQUENCES IN SCHEMA my_db.my_schema
    TO DATABASE ROLE my_db.read_role;

GRANT INHERITED USAGE ON ALL STAGES IN SCHEMA my_db.my_schema
    TO DATABASE ROLE my_db.read_role;

GRANT INHERITED USAGE ON ALL FILE FORMATS IN SCHEMA my_db.my_schema
    TO DATABASE ROLE my_db.read_role;

GRANT INHERITED SELECT ON ALL TABLES IN DATABASE my_db
    TO ROLE my_role;

GRANT INHERITED SELECT, INSERT ON ALL TABLES IN SCHEMA my_db.my_schema
    TO APPLICATION my_app;

GRANT INHERITED USAGE ON ALL SCHEMAS IN DATABASE my_db
    TO ROLE my_role;

GRANT INHERITED USAGE ON ALL WAREHOUSES IN ACCOUNT
    TO ROLE my_role;

GRANT INHERITED SELECT ON ALL TABLES IN ACCOUNT
    TO ROLE my_role;

REVOKE INHERITED SELECT ON ALL TABLES IN SCHEMA my_db.my_schema
    FROM DATABASE ROLE my_db.read_role;

REVOKE INHERITED USAGE ON ALL FILE FORMATS IN SCHEMA my_db.my_schema
    FROM DATABASE ROLE my_db.read_role;

REVOKE INHERITED SELECT ON ALL TABLES IN ACCOUNT
    FROM ROLE my_role;
